#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_glassdock.py — Kit 29h [glassdock-v1] — الأيقونات والإيموجي كيولّيو زجاج
التركيب من جذر الفرونت:  python patch_glassdock.py   (ولا INSTALL_FRONTEND.bat)

الأمان:
  • GlassIcon/GlassDock جداد: إلا موجودين بلا ماركر [glassdock-v1] → exit 1 (fail-closed) + diag
  • كل ملف معدل: backup .bak-kit29h (أول مرة برك) · أزواج lenient (drift → skip + log)
  • idempotent — ملفات مركبة مسبقاً كيتسكيبيو
"""
import base64, json, os, shutil, sys, time

SKIP_DIRS = {"node_modules", ".next", ".git", ".vercel", ".turbo", "dist", "build", "coverage", ".sentinel"}
F = json.loads("""{"glass_icon": "", "glass_dock": "", "est_v6": "", "pairs": ""}""")

def B(k):
    return base64.b64decode(F[k]).decode("utf-8")

def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()

def write(path, content):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)

def diag(msg):
    try:
        os.makedirs("kit29h-diag", exist_ok=True)
        with open(os.path.join("kit29h-diag", "manifest.txt"), "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S") + " | " + msg + "\n")
    except Exception:
        pass

print("══ Kit 29h [glassdock-v1] — الأيقونات والإيموجي كيولّيو زجاج ══")
print("")

if not (os.path.exists("next.config.ts") or os.path.exists("next.config.js")):
    print("❌ خدم من جذر الفرونت (المجلد اللي فيه next.config.ts)")
    sys.exit(1)

changed = skipped = pair_ok = pair_skip = 0

# ── 1) الملفات الجديدة ──
for key, relp, name in [("glass_icon", "app/components/ui/GlassIcon.tsx", "GlassIcon"),
                        ("glass_dock", "app/components/ui/GlassDock.tsx", "GlassDock")]:
    if os.path.exists(relp):
        c = read(relp)
        if "[glassdock-v1]" in c:
            print("  ⏭️ " + name + " مركب مسبقاً")
            skipped += 1
        else:
            print("❌ " + relp + " موجود بلا ماركر [glassdock-v1] — ما نلمسوش (fail-closed)")
            diag(relp + " exists without marker")
            sys.exit(1)
    else:
        write(relp, B(key))
        print("  ✚ " + relp)
        changed += 1

# ── 2) DeliveryEstimator → v6 (تعويض كامل — standalone من v2) ──
est_path = None
for root in ("app", "components", "src"):
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for nm in ("DeliveryEstimator.tsx", "DeliveryEstimator.jsx"):
            if nm in filenames:
                est_path = os.path.join(dirpath, nm)
                break
if est_path:
    c = read(est_path)
    if "[cj-eta-v6]" in c:
        print("  ⏭️ DeliveryEstimator v6 مركب مسبقاً")
        skipped += 1
    else:
        bak = est_path + ".bak-kit29h"
        if not os.path.exists(bak):
            shutil.copy2(est_path, bak)
        write(est_path, B("est_v6"))
        print("  ✚ " + est_path + " → v6 [cj-eta-v6] (زجاجية: Plane/Truck/Zap/Check)")
        changed += 1
else:
    print("  ⚠ DeliveryEstimator ما لقيتوش — كيتسكيب (اختياري فالكيت)")
    diag("estimator missing")

# ── 3) الأزواج الجراحية ──
PAIRS = json.loads(B("pairs"))
for relp, plist in sorted(PAIRS.items()):
    if not os.path.exists(relp):
        alt = relp + ".tsx"
        if os.path.exists(alt):
            relp = alt
        else:
            print("  ⚠ " + relp + " ما لقيتوش فشجرك — كيتسكيب (drift)")
            pair_skip += 1
            continue
    c = read(relp)
    sentinel = "components/ui/GlassDock" if relp == "app/layout.tsx" else "components/ui/GlassIcon"
    if sentinel in c:
        print("  ⏭️ " + relp + " مركب مسبقاً")
        skipped += 1
        continue
    applied = 0
    for old, new, exp in plist:
        n = c.count(old)
        if n == exp:
            c = c.replace(old, new)
            applied += 1
        elif n == 0:
            pair_skip += 1
        else:
            print("  ⚠ " + relp + " — زوج بعدد غير متوقع (" + str(n) + "≠" + str(exp) + ") — سكيب")
            pair_skip += 1
    if applied:
        bak = relp + ".bak-kit29h"
        if not os.path.exists(bak):
            shutil.copy2(relp, bak)
        write(relp, c)
        print("  ✚ " + relp + f" ({applied}/{len(plist)} زوج)")
        changed += 1
    else:
        print("  ⚠ " + relp + " — حتى زوج ما تطبق (drift كامل) — الملف ما تلمسش")

print("")
print(f"[SUMMARY] جداد/مبدلين: {changed} · سكيب: {skipped} · أزواج: {pair_ok if False else ''}تطبقو + {pair_skip} تسكيپاو")
print("[NEXT] npm run build (خاصو يعدّي بلا أخطاء) ثم deploy")
print("      من بعد: 🚚 Free Delivery زجاجية + dock عائم فأسفل الشاشة")
sys.exit(0)
